import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"32、【恆】 巽下震上","description":"子夏易傳 - 32、【恆】 巽下震上","frontmatter":{"title":"32、【恆】 巽下震上","description":"子夏易傳 - 32、【恆】 巽下震上"},"headers":[],"relativePath":"classics/zixia/034.md","filePath":"classics/zixia/034.md"}'),i={name:"classics/zixia/034.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_32、【恆】-巽下震上" tabindex="-1">32、【恆】 巽下震上 <a class="header-anchor" href="#_32、【恆】-巽下震上" aria-label="Permalink to “32、【恆】 巽下震上”">​</a></h1><p>卦辭：恆亨無咎，利貞，利有攸往。</p><p>彖曰：恆，久也。剛上而柔下，雷風相與。巽而動，剛柔相應，恆。恆亨無咎，利貞，久於其道也。天地之道，恆久而不已也。利有攸往，終則有始也。日月得天而能久照，四時變化而能久成，聖人久於其道而天下化成。觀其所恆而天地萬物之情可見矣。恆而得其久也。</p><p>子夏：剛上而柔下，剛柔交而下承也。雷行風從，増其大逺矣。巽而動，往無不從也。剛柔皆應外內逹也。此可久之道也。能久則通矣。保其無咎矣。利而得正矣。久而得其終始之道也。則何往而不利焉。天地恆久也，而萬物生。聖人恆久也，而天下化。以恆久而觀之，天地萬物之情得其恆者，長也。</p><p>象曰：雷風，恆。君子以立不易方。</p><p>子夏：雷之震，風必從之。君子行，必由其道。得其恆而増，其恆而増其大也。故獨立其所不以物易。</p><p>初六，浚恆，貞兇。無攸利。</p><p>象曰：浚恆之兇，始求深也。</p><p>子夏：恆者，久於其道，不煩而物自歸也。處於極下，深底者也。不修其恆，不度其分，遂求其應，初以深極而求於人。人斯竭之矣，何以終乎。正之兇而無所利也。</p><p>九二，悔亡。</p><p>象曰：九二，悔亡。能久中也。</p><p>子夏：非其位久失道也，剛而自正，退而久中，可以悔亡。</p><p>九三，不恆其徳，或承之羞，貞吝。</p><p>象曰：不恆其徳，無所容也。</p><p>子夏：三者，終下至上之地，進退之所也。不能修徳守位，而復上以求應，無其恆也，何以容哉。以是為政可惜者也。</p><p>九四，田無禽。</p><p>象曰：久非其位，安得禽也。</p><p>子夏：承上之地，柔以奉上而剛居之。求應於下位已失矣，安所獲乎。</p><p>六五，恆其徳，貞婦人吉，夫子兇。</p><p>象曰：婦人貞吉，從一而終也。夫子制義，從婦兇也。</p><p>子夏：從係以為正，守中而為恆，婦人以之吉也，夫子可以制義矣。而從人之政，狹之至矣，固其兇也。</p><p>上六，振恆，兇。</p><p>象曰：振恆，在上大無功也。</p><p>子夏：極上，終盡之地，柔振而將久之道窮也，久何之乎。雖有其應，不足振也。失時之極，無功已矣，兇之道也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
